import { useDispatch, useSelector } from '@src/lib/redux';
import React, { useState } from 'react';
import { View, Text, TextInput, StyleSheet } from 'react-native';
import {
  selectLocation,
  selectLocationError,
  selectLocationStatus,
} from '../selector';
import { fetchLocationDetail } from '../thunk';
import { ActionButton } from '@core/ui';

export const WeatherSearch: React.FC = () => {
  const [query, setQuery] = useState('');

  const dispatch = useDispatch();

  const location = useSelector(selectLocation);
  const status = useSelector(selectLocationStatus);
  const error = useSelector(selectLocationError);

  const handleSearch = async () => {
    try {
      dispatch(fetchLocationDetail(query));
    } catch (err) {
      console.error('Failed to fetch weather:', err);
    }
  };

  return (
    <View style={styles.container}>
      <TextInput
        value={query}
        onChangeText={setQuery}
        placeholder="Enter location"
        style={styles.input}
      />
      <ActionButton
        title={status === 'loading' ? 'Searching...' : 'Search'}
        onPress={handleSearch}
      />

      {location && (
        <View style={styles.infoContainer}>
          <Text style={styles.locationText}>
            Location: {location.name}, {location.country}
          </Text>
        </View>
      )}

      {error && <Text style={styles.error}>{error}</Text>}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    padding: 20,
  },
  input: {
    borderWidth: 1,
    borderColor: '#ddd',
    padding: 10,
    marginBottom: 10,
    borderRadius: 5,
  },
  button: {
    backgroundColor: '#007AFF',
    padding: 10,
    borderRadius: 5,
  },
  buttonText: {
    color: 'white',
    textAlign: 'center',
  },
  error: {
    color: 'red',
    marginTop: 10,
  },
  infoContainer: {
    marginTop: 20,
  },
  locationText: {
    fontSize: 16,
    fontWeight: '500',
  },
});
