import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { GetClientInfoHandler } from '@src/application/common/get_client_info/get_client_info_handle';

export const fetchClientInfo = createAsyncThunk('clientInfo/get', async (payload: GetClientInfoPayload['data']) => {
    const clientInfo = container.get<GetClientInfoHandler>(TYPES.GetClientInfoHandler);
    // console.log('\x1b[36m', 'fetchClientInfo => thunk');
    const query = new Query<GetClientInfoPayload>({
        query: {
            requestId: 'd7777357-be44-4a08-897d-46625ec59c9a',
            channel: 'Mobile',
            ipRequest: '128.0.0.1',
            language: 'vn',
            deviceInfo: {
                deviceId: '123-1232-123',
                deviceName: 'Testing',
                os: 'IOS',
                osVersion: '15',
            },
            data: payload,
        },
    });
    return await clientInfo.handle(query);
});
